/* ---------- notatie ----------
   $...$ = formule; x^2 = macht; [[teller|noemer]] = breuk */
function mth(x){
  x=x.replace(/-/g,'−');
  x=x.replace(/\^\{([^}]*)\}/g,'<sup>$1</sup>');
  x=x.replace(/_\{([^}]*)\}/g,'<sub>$1</sub>');
  x=x.replace(/\^(−?[0-9]+|[a-z])/g,'<sup>$1</sup>');
  x=x.replace(/\[\[(.+?)\|(.+?)\]\]/g,'<span class="fr"><span>$1</span><span>$2</span></span>');
  return x;
}
function fmt(s){return String(s).replace(/\$([^$]+)\$/g,(_,x)=>'<span class="m">'+mth(x)+'</span>')}
const neg=v=>(typeof v==='number'&&v<0)?'−'+(-v):v;

/* grafiek in een assenstelsel met roosterlijnen (zoals op het ruitjespapier van het practicum) */
let clipN=0;
function plot(o){
  const [x0,x1]=o.x,[y0,y1]=o.y,ux=o.ux||o.u||20,uy=o.uy||o.u||20,p=22;
  const W=(x1-x0)*ux+2*p+10,H=(y1-y0)*uy+2*p+12;
  const X=x=>+(p+10+(x-x0)*ux).toFixed(1),Y=y=>+(p+12+(y1-y)*uy).toFixed(1);
  const id='clip'+(++clipN),sx=o.sx||2,sy=o.sy||2,gx=o.gx||1,gy=o.gy||1;
  const ax=x0,ay=y0;
  let g='';
  for(let x=x0;x<=x1+1e-9;x+=gx)g+=`<line class="g" x1="${X(x)}" y1="${Y(y0)}" x2="${X(x)}" y2="${Y(y1)}"/>`;
  for(let y=y0;y<=y1+1e-9;y+=gy)g+=`<line class="g" x1="${X(x0)}" y1="${Y(y)}" x2="${X(x1)}" y2="${Y(y)}"/>`;
  g+=`<line class="ax" x1="${X(ax)}" y1="${Y(y0)}" x2="${X(ax)}" y2="${Y(y1)}"/><line class="ax" x1="${X(x0)}" y1="${Y(ay)}" x2="${X(x1)}" y2="${Y(ay)}"/>`;
  if(!o.noNum){
    for(let x=x0;x<=x1+1e-9;x+=sx)g+=`<text x="${X(x)}" y="${Y(ay)+14}" text-anchor="middle">${neg(+x.toFixed(2))}</text>`;
    for(let y=y0;y<=y1+1e-9;y+=sy)g+=`<text x="${X(ax)-5}" y="${Y(y)+4}" text-anchor="end">${neg(+y.toFixed(2))}</text>`;
  }
  g+=`<text class="al" x="${X(x1)}" y="${Y(ay)-6}" text-anchor="end">${o.xl||'x'}</text><text class="al" x="${X(ax)+6}" y="${Y(y1)-8}">${o.yl||'y'}</text>`;
  (o.fns||[]).forEach(fn=>{
    const a=fn.from??x0,b=fn.to??x1,N=200;let d='';
    for(let i=0;i<=N;i++){const x=a+(b-a)*i/N,y=fn.f(x);d+=(i?'L':'M')+X(x)+' '+Y(y)+' '}
    g+=`<path class="${fn.c||'ln'}" clip-path="url(#${id})" d="${d}"/>`;
    if(fn.lab)g+=`<text class="fl" x="${X(fn.lab[0])}" y="${Y(fn.lab[1])}">${fn.lab[2]}</text>`;});
  return `<svg class="plot" viewBox="0 0 ${W} ${H}" style="max-width:${o.max||W}px" role="img" aria-label="${o.label||'grafiek'}"><defs><clipPath id="${id}"><rect x="${X(x0)}" y="${Y(y1)-2}" width="${(x1-x0)*ux+2}" height="${(y1-y0)*uy+4}"/></clipPath></defs>${g}</svg>`;
}

/* een thermometer met schaalverdeling: min, max, stap van de getallen, stap van de streepjes, stand */
function therm(o){
  const n=Math.round((o.max-o.min)/o.tick),H=Math.max(170,Math.min(280,n*7)),top=30,bot=top+H;
  const Y=v=>+(bot-(v-o.min)/(o.max-o.min)*H).toFixed(1);
  let g=`<rect class="tube" x="34" y="${top-8}" width="14" height="${H+16}" rx="7"/><circle class="tube" cx="41" cy="${bot+20}" r="13"/>`;
  if(o.val!=null)g+=`<rect class="col" x="38" y="${Y(o.val)}" width="6" height="${bot+12-Y(o.val)}"/><circle class="col" cx="41" cy="${bot+20}" r="9"/>`;
  for(let i=0;i<=n;i++){const v=+(o.min+i*o.tick).toFixed(2),big=Math.abs(v/o.lab-Math.round(v/o.lab))<1e-6;
    g+=`<line class="tk" x1="50" y1="${Y(v)}" x2="${big?64:57}" y2="${Y(v)}"/>`;
    if(big)g+=`<text x="68" y="${Y(v)+4}">${neg(v)}</text>`;}
  g+=`<text x="41" y="${top-12}" text-anchor="middle">°C</text>`;
  return `<svg class="therm" viewBox="0 0 110 ${bot+40}" width="110" role="img" aria-label="thermometer">${g}</svg>`;
}

/* afkoelgrafiek van het practicum Melk of praatje (t in s, T in °C) */
const kA=t=>20+61*Math.exp(-0.002*t);                        // direct melk erin: start 81 °C
const kB=t=>t<300?20+80*Math.exp(-0.002*t):20+32.1*Math.exp(-0.002*(t-300)); // eerst 5 min wachten, dan melk
const MELK=plot({x:[0,440],y:[0,100],ux:0.75,uy:2.4,sx:80,sy:10,gx:40,gy:10,xl:'t (s)',yl:'T (°C)',
  fns:[{f:kA,c:'ln2'},{f:kB,c:'ln'}],label:'twee afkoelgrafieken'});
const MELKLEG='<div class="legend"><span><i style="background:var(--pen)"></i>Direct melk toevoegen</span><span><i style="background:var(--bad)"></i>5 min wachten, dan melk</span></div>';


