/* rekensprint: korte sommen die je typt */
const R=(a,b)=>a+Math.floor(Math.random()*(b-a+1));
const SPRINT=[
 ()=>{const c=R(-40,120);return {q:`$${c}$ °C = … K`,a:c+273,e:'K'}},
 ()=>{const k=R(150,400);return {q:`$${k}$ K = … °C`,a:k-273,e:'°C'}},
 ()=>{const g=R(1,40)*50;return {q:`$${g}$ g = … kg`,a:g/1000,e:'kg'}},
 ()=>{const m=R(1,30)*250;return {q:`$${m}$ mL = … L`,a:m/1000,e:'L'}},
 ()=>{const m=R(1,9),s=R(1,9)*10;return {q:`$${m}$ min en $${s}$ s = … s`,a:m*60+s,e:'s'}},
 ()=>{const v=R(2,20)*10,r=[0.5,2,2.5,3,4,8][R(0,5)];return {q:`$m = ${String(v*r).replace('.',',')}$ g, $V = ${v}$ cm^3. $ρ$ = … g/cm^3`,a:r,e:'g/cm³'}},
 ()=>{const m=R(1,5),d=R(1,8)*10;return {q:`$${m}$ kg water, $${d}$ °C warmer ($c = 4,2$). Warmte = … kJ`,a:+(m*4.2*d).toFixed(1),e:'kJ'}},
 ()=>{const g=R(1,10)*10;return {q:`$${g}$ g ijs smelten (334 kJ/kg). Warmte = … kJ`,a:+(g/1000*334).toFixed(2),e:'kJ'}}
];
